import java.util.*;

public class Main {
    static int countStudents(int[] students, int[] sandwiches) {
        Deque<Integer> queue = new ArrayDeque<>();
        for (int s : students) queue.addLast(s);
        List<Integer> stack = new ArrayList<>();
        for (int sw : sandwiches) stack.add(sw);

        int rotationsWithoutMatch = 0;
        while (!queue.isEmpty() && rotationsWithoutMatch < queue.size()) {
            if (queue.peekFirst().equals(stack.get(0))) {
                queue.pollFirst();
                stack.remove(0);
                rotationsWithoutMatch = 0;
            } else {
                queue.addLast(queue.pollFirst());
                rotationsWithoutMatch++;
            }
        }
        return queue.size();
    }

    public static void main(String[] args) {
        System.out.println(countStudents(new int[]{1, 1, 1, 0, 0, 1}, new int[]{1, 0, 0, 0, 1, 1}));
        System.out.println(countStudents(new int[]{1, 1, 0, 0}, new int[]{0, 1, 0, 1}));
    }
}

