#include <bits/stdc++.h>
using namespace std;

int countStudents(vector<int>& students, vector<int>& sandwiches) {
    deque<int> queue(students.begin(), students.end());
    deque<int> stack(sandwiches.begin(), sandwiches.end());

    int rotationsWithoutMatch = 0;
    while (!queue.empty() && rotationsWithoutMatch < (int)queue.size()) {
        if (queue.front() == stack.front()) {
            queue.pop_front();
            stack.pop_front();
            rotationsWithoutMatch = 0;
        } else {
            queue.push_back(queue.front());
            queue.pop_front();
            rotationsWithoutMatch++;
        }
    }
    return queue.size();
}

int main() {
    vector<int> s1 = {1, 1, 1, 0, 0, 1};
    vector<int> w1 = {1, 0, 0, 0, 1, 1};
    cout << countStudents(s1, w1) << endl;
    vector<int> s2 = {1, 1, 0, 0};
    vector<int> w2 = {0, 1, 0, 1};
    cout << countStudents(s2, w2) << endl;
    return 0;
}

